 using System.ComponentModel;
 using System.Net;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Hosting;
 using Microsoft.Extensions.Logging;
 using OpenAI;

 var builder = Host.CreateApplicationBuilder(args);

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 builder.Services.AddChatClient(
     new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

 builder.Services.AddSingleton<Notebook>();

 builder.Logging.SetMinimumLevel(LogLevel.Warning);

 using var host = builder.Build();

 var chatClient = host.Services.GetRequiredService<IChatClient>();
 var notebook = host.Services.GetRequiredService<Notebook>();

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(SearchWeb),
     AIFunctionFactory.Create(notebook.SaveNote),
     AIFunctionFactory.Create(notebook.GetNotes),
 };

 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research assistant. When given a topic:
         1. Search the web multiple times with different queries to gather information.
         2. Save important findings as notes using the save_note tool.
         3. After gathering enough information, retrieve all notes and produce a
            well-structured summary with key findings and sources.
         Be thorough — perform at least 2-3 searches before summarizing.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 Console.WriteLine("=== Research Agent ===");
 Console.Write("Enter a topic to research: ");
 var topic = Console.ReadLine()?.Trim();

 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");

 var session = await agent.CreateSessionAsync();

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a summary: {topic}",
     session,
     runOptions))
 {
     if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine();

 // --- Tool definitions ---

 [Description("Search the web for information on a query. Returns a list of search results with titles, snippets, and URLs.")]
 static string SearchWeb(
     [Description("The search query string")] string query)
 {
     // Simulated web search results for demonstration.
     // Replace with a real search API (e.g., Bing Search API) for production use.
     var encodedQuery = WebUtility.UrlEncode(query);
     var results = new[]
     {
         new
         {
             Title = $"Overview of {query} - Wikipedia",
             Snippet = $"A comprehensive overview covering the key aspects, history, and significance of {query}.",
             Url = $"https://en.wikipedia.org/wiki/{encodedQuery}",
         },
         new
         {
             Title = $"Latest Research on {query}",
             Snippet = $"Recent studies and developments related to {query}, including expert analysis and findings.",
             Url = $"https://research.example.com/{encodedQuery}",
         },
         new
         {
             Title = $"{query}: A Practical Guide",
             Snippet = $"Step-by-step guide explaining {query} with real-world examples and best practices.",
             Url = $"https://guide.example.com/{encodedQuery}",
         },
     };

     return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
 }

 // --- Notebook for note-taking ---

 sealed class Notebook
 {
     private readonly List<string> _notes = [];

     [Description("Save a research note. Use this to record important findings from search results.")]
     public string SaveNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         return $"Note #{_notes.Count} saved.";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
         {
             return "No notes saved yet.";
         }

         return string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
     }
 }

